function c(t){const a=Math.min(Math.floor((t-1)/2)+2,8),o=Math.floor(Math.random()*360),n=50+Math.floor(Math.random()*30),r=35+Math.floor(Math.random()*25),f=Math.max(3,35-t*2.5),i=(Math.random()>.5?1:-1)*f,s=(Math.random()>.5?1:-1)*Math.max(1,f*.4),h=(Math.random()>.5?1:-1)*Math.max(1,f*.3),e=a*a,M=Math.floor(Math.random()*e);return{gridSize:a,baseHue:o,baseSat:n,baseLit:r,diffIndex:M,diffHue:o+s,diffSat:Math.max(10,Math.min(90,n+h)),diffLit:Math.max(15,Math.min(75,r+i))}}function m(t){return`hsl(${t.baseHue}, ${t.baseSat}%, ${t.baseLit}%)`}function d(t){return`hsl(${t.diffHue}, ${t.diffSat}%, ${t.diffLit}%)`}function u(t){return t<=4?10:t<=8?12:t<=12?14:t<=16?16:Math.min(20,16+Math.floor((t-16)/4)*2)}function x(t,a){const o=100+t*20,n=u(t)*1e3,r=Math.max(0,Math.floor((1-a/n)*50));return o+r}export{m as a,c as b,x as c,d as g};
